style.css:
body {
    margin: 0;
    min-height: 100vh;
    background-color: #050607;
    background-image:
        radial-gradient(ellipse at 20% 30%, transparent 0 80px, rgba(255,255,255,.7) 82px 84px, transparent 86px),
        radial-gradient(ellipse at 70% 60%, transparent 0 120px, rgba(255,255,255,.45) 122px 124px, transparent 126px),
        radial-gradient(ellipse at 90% 20%, transparent 0 100px, rgba(255,255,255,.5) 102px 104px, transparent 106px);
    background-size: 500px 500px, 700px 700px, 600px 600px;
    animation: topoMove 12s ease-in-out infinite alternate;
}

@keyframes topoMove {
    0% {
        background-position: 0 0, 0 0, 0 0;
    }
    100% {
        background-position: 60px 40px, -80px 50px, 40px -60px;
    }
}
